tools.input:
mkdir -p <trial>/work && cd <trial> && cat > work/a.tuft <<'E'
@h := find text "retain_read" in "crates/" at "9e0c8d648852e2e6f27c6f9517c71d8e5ea67a49" limit 500;
@e := retain @h around lines 0;
@v := project @e [path, line, excerpt(max_chars: 300)] sort [path asc, line asc];
emit @v budget_tokens 4000;
E
../../bin/writfold tuft run work/a.tuft --repo $PWD/repo --state $PWD/state
